function submit(PDO $pdo,string $file,array $post,array $session,array $permissions=[]):array{
    $_FILES=[];$_POST=$post;$_SESSION=$session;$_SERVER['REQUEST_METHOD']='POST';unset($GLOBALS['demo_redirect']);$can_edit=$permissions['edit']??true;$can_manage=$permissions['manage']??true;$isDriver=$permissions['driver']??false;$driver_ambulance=$permissions['driver_ambulance']??null;$isCoordinator=$permissions['coordinator']??false;$coord_type_id=$permissions['coord_type_id']??null;$isAdmin=$permissions['admin']??true;$message='';$error='';$error_message='';$success='';
    $s=file_get_contents(__DIR__.'/planning/original-writer-patch-v9/patched/'.$file);
    $start=match($file){'ambulance_running.php'=>'// 1. Process Form Submissions','off_road_ambulances.php'=>'// Handle Actions',default=>''};
    // Avoid interpolation in the literal source anchor.
    if($file==='ambulance_analytics.php')$start="if ((\$_SERVER['REQUEST_METHOD'] ?? 'GET') === 'POST' && \$isAdmin";
    $end=match($file){'ambulance_running.php'=>'// 2. Fetch Context Data','off_road_ambulances.php'=>"if (isset(\$_GET['msg']) && \$_GET['msg'] === 'repaired')",default=>'// 1. Fetch Filters'};
    $a=strpos($s,$start);$b=strpos($s,$end,$a?:0);if($a===false||$b===false)throw new RuntimeException('Staged handler anchors missing');$code=substr($s,$a,$b-$a);
    // Preserve redirect result without terminating this isolated test process.
    $code=str_replace("header('Location: '.\$mapaResult['redirect']); exit;","\$GLOBALS['demo_redirect'] = \$mapaResult['redirect'];",$code);
    eval($code);return ['message'=>$message?:$success,'error'=>$error?:$error_message,'redirect'=>$GLOBALS['demo_redirect']??null];
}
